    print(f"Song {song_id}: {song['title']} by {[a['name'] for a in song['artists']]}")

# Remove matched songs from all existing playlists
matched_song_ids = [128, 257, 131, 261, 280, 29, 162, 43, 172, 308, 311, 74, 207, 127]
playlist_ids = [p['playlist_id'] for p in playlists]

for pid in playlist_ids:
    # Get current songs in this playlist from playlist_songs dict
    current_songs = playlist_songs.get(pid, [])
    for song_id in matched_song_ids:
