steps.code:
# Get songs for each playlist (excluding the new "Old Songs" playlist)
playlist_songs = {}
for pl in all_playlists:
    if pl['playlist_id'] == 654:
        continue  # skip the new playlist we created
    pl_detail = apis.spotify.show_playlist(
        playlist_id=pl['playlist_id'],
        access_token=login_result["access_token"]
    )
    playlist_songs[pl['playlist_id']] = pl_detail['songs']
    print(f"Playlist '{pl['title']}' has {len(pl_detail['songs'])} songs")

# Print a sample to verify structure
print("\nSample song entry:", playlist_songs[160][0] if playlist_songs[160] else "empty")

