steps.code:
# Verify that all archived songs have been removed from all playlists except "Old Songs" (654)
# and that "Old Songs" contains all archived songs.

# Extract set of archived song IDs
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}

# Check each playlist except 654
for playlist in all_playlists:
    if playlist["playlist_id"] == 654:
        continue
    playlist_detail = apis.spotify.show_playlist(playlist_id=playlist["playlist_id"], access_token=login_result["access_token"])
    songs_in_playlist = playlist_detail.get("songs", [])
    song_ids_in_playlist = {song["id"] for song in songs_in_playlist}
    remaining_archived = song_ids_in_playlist & archived_song_ids
    if remaining_archived:
        print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) still contains archived songs: {remaining_archived}")
        # Remove them
        for song_id in remaining_archived:
            result = apis.spotify.remove_song_from_playlist(playlist_id=playlist["playlist_id"], song_id=song_id, access_token=login_result["access_token"])
            print(f"  Removed song_id {song_id}: {result}")
    else:
        print(f"Playlist {playlist['playlist_id']} ({playlist['title']}) is clean.")

# Verify "Old Songs" playlist contains all archived songs
old_songs_detail = apis.spotify.show_playlist(playlist_id=654, access_token=login_result["access_token"])
old_songs_ids = {song["id"] for song in old_songs_detail.get("songs", [])}
missing = archived_song_ids - old_songs_ids
if missing:
    print(f"Old Songs playlist is missing archived songs: {missing}")
    # Add them if missing
    for song_id in missing:
        result = apis.spotify.add_song_to_playlist(playlist_id=654, song_id=song_id, access_token=login_result["access_token"])
        print(f"  Added song_id {song_id}: {result}")
else:
    print("Old Songs playlist contains all archived songs.")

