steps.code:
# Build a mapping of song title+artists to song_id by searching for each song
song_id_map = {}
for song in songs_to_archive:
    query = song['title'] + ' ' + ' '.join(song['artists'])
    result = apis.spotify.search_songs(query=query, access_token=spotify_token)
    # Find the first result that matches title and at least one artist
    found = None
    for item in result:
        if item['title'].lower() == song['title'].lower():
            item_artists = [a['name'].lower() for a in item['artists']]
            song_artists = [a.lower() for a in song['artists']]
            if any(artist in item_artists for artist in song_artists):
                found = item['song_id']
                break
    if found is not None:
        song_id_map[(song['title'], tuple(song['artists']))] = found
    else:
        print(f"Could not find song: {song['title']} by {song['artists']}")

print(f"Found {len(song_id_map)} songs out of {len(songs_to_archive)}")
print(song_id_map)

