# Verify all playlists no longer contain target songs, and new playlist has all target songs
target_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}
playlist_ids = [513, 514, 515, 516, 517, 518, 519]

for pid in playlist_ids:
    pl = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    song_ids = {s['id'] for s in pl['songs']}
    remaining = song_ids & target_song_ids
    print(f"Playlist {pid} ({pl['title']}): remaining target songs = {remaining}")

# Check new playlist
new_pl = apis.spotify.show_playlist(playlist_id=654, access_token=spotify_token)
new_song_ids = {s['id'] for s in new_pl['songs']}
missing = target_song_ids - new_song_ids
print(f"New playlist missing target songs: {missing}")

