steps.code:
# Parse the note content to extract songs and their release status
content = note['content']
lines = content.split('\n')
songs = []
for line in lines:
    if line.startswith('- '):
        # Remove leading "- "
        line = line[2:]
        # Split by " BY " to get title and artist part
        if ' BY ' in line:
            title_part, artist_part = line.split(' BY ', 1)
            # Split artist_part by " RELEASED_AT " to get artists and release info
            if ' RELEASED_AT ' in artist_part:
                artists_str, release = artist_part.split(' RELEASED_AT ', 1)
                artists = [a.strip() for a in artists_str.split(',')]
                songs.append({'title': title_part.strip(), 'artists': artists, 'release': release.strip()})
            else:
                # No release info? unlikely
                songs.append({'title': title_part.strip(), 'artists': [], 'release': None})
        else:
            # No " BY "? skip
            pass

# Print songs with TODO
for s in songs:
    if s['release'] == 'TODO':
        print(s)

