from datetime import datetime

# Map song titles to release month/year
release_map = {}
for title, iso_date in release_dates.items():
    dt = datetime.fromisoformat(iso_date)
    release_map[title] = f"{dt.month:02d}/{dt.year}"

# Reconstruct the content
new_lines = []
for line in content.strip().split('\n'):
    if line.startswith('# '):
        new_lines.append(line)
        continue
    if not line.strip():
        new_lines.append(line)
        continue
    # Parse the line
    line_stripped = line.strip()
    if line_stripped.startswith('- '):
        line_stripped = line_stripped[2:]
    # Split on " RELEASED_AT "
    if ' RELEASED_AT ' in line_stripped:
        song_part, release_part = line_stripped.split(' RELEASED_AT ', 1)
        # Extract title (before " BY ")
        if ' BY ' in song_part:
            title = song_part.split(' BY ', 1)[0]
        else:
            title = song_part
        # If title in release_map, replace
        if title in release_map:
            new_release = release_map[title]
            # Reconstruct the line with original formatting (preserve leading "- " if present)
            if line.startswith('- '):
                new_line = f"- {song_part} RELEASED_AT {new_release}"
            else:
                new_line = f"{song_part} RELEASED_AT {new_release}"
            new_lines.append(new_line)
        else:
            # Keep as is
            new_lines.append(line)
    else:
        new_lines.append(line)

new_content = '\n'.join(new_lines)
print(new_content)

