# Let's search for the next few songs to verify we can find exact matches
# We'll create a helper function to find the exact song
def find_song(title, artists_str):
    query = title + " " + artists_str
    results = apis.spotify.search_songs(query=query, access_token=spotify_token, page_limit=20)
    # Normalize artist names from note
    note_artists = set([a.strip() for a in artists_str.split(',')])
    for song in results:
        if song['title'].lower() == title.lower():
            song_artists = set([a['name'] for a in song['artists']])
            if song_artists == note_artists:
                return song
    return None

# Test for Caught in a Web of Lies
song = find_song("Caught in a Web of Lies", "Hazel Winter, Ava Morgan")
if song:
    print(song['title'], song['release_date'])
else:
    print("Not found")

