steps.code:
# Get release dates for all liked songs using show_song API
release_dates = {}
for song in liked_songs:
    song_id = song['song_id']
    details = apis.spotify.show_song(song_id=song_id, access_token=spotify_token)
    if 'release_date' in details:
        release_dates[song_id] = details['release_date']
    else:
        print(f"Error for song {song_id}: {details}")

print(f"Got release dates for {len(release_dates)} songs")
# Print mapping
for sid, rd in release_dates.items():
    print(f"{sid}: {rd}")

